const express = require("express");
const { mkdirSync } = require("node:fs");
const { DatabaseSync } = require("node:sqlite");

const app = express();
app.use(express.json());

function openEventsDatabase() {
  mkdirSync("data", { recursive: true });

  const database = new DatabaseSync("data/events.db");

  database.exec(`
    CREATE TABLE IF NOT EXISTS events (
      id INTEGER PRIMARY KEY,
      title TEXT NOT NULL,
      category TEXT NOT NULL
    )
  `);

  const countRow = database
    .prepare("SELECT COUNT(*) AS count FROM events")
    .get();

  if (countRow.count === 0) {
    const seedEvent = database.prepare(`
      INSERT INTO events (id, title, category)
      VALUES (?, ?, ?)
    `);

    seedEvent.run(1, "Open Mic", "arts");
    seedEvent.run(2, "Career Fair", "career");
    seedEvent.run(3, "Gallery Walk", "arts");
  }

  return database;
}

const db = openEventsDatabase();

function validateEventInput(input, { partial = false } = {}) {
  const fields = [];

  if (!partial || input.title !== undefined) {
    if (!input.title || typeof input.title !== "string") {
      fields.push("title");
    }
  }

  if (!partial || input.category !== undefined) {
    if (!input.category || typeof input.category !== "string") {
      fields.push("category");
    }
  }

  return fields;
}

