  return res.status(status).json({
    error: message,
    ...extra,
  });
}

function listEvents(category) {
  if (category) {
    return db
      .prepare(`
        SELECT id, title, category
        FROM events
        WHERE category = ?
        ORDER BY id
      `)
      .all(category);
